# filename: reconciliation_service/main.py

import logging
import uuid
from contextlib import asynccontextmanager
from datetime import datetime, timezone

from fastapi import BackgroundTasks, FastAPI, Query
from models import ReconcileRequest, ScheduleConfig, TriggerType
from reconciler import Reconciler
from scheduler import ReconciliationScheduler

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(name)s] %(levelname)s: %(message)s")

reconciler  = Reconciler()
sched       = ReconciliationScheduler(reconciler)


@asynccontextmanager
async def lifespan(app: FastAPI):
    sched.start()
    yield
    sched.shutdown()


app = FastAPI(
    title="Reconciliation Service",
    version="2.0.0",
    description="Gateway → Ledger → Bank → Merchant reconciliation with EOD scheduler",
    lifespan=lifespan
)


# ── Health ────────────────────────────────────────────────────────────────────

@app.get("/health")
def health():
    return {
        "status"    : "ok",
        "service"   : "reconciliation_service",
        "timestamp" : datetime.now(tz=timezone.utc),
        "scheduler" : sched.status()
    }


# ── Manual trigger ────────────────────────────────────────────────────────────

@app.post("/reconcile/run")
async def run_manual(req: ReconcileRequest, background_tasks: BackgroundTasks):
    run_id = f"recon_manual_{datetime.now(tz=timezone.utc).strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}"
    background_tasks.add_task(reconciler.run, run_id, req, TriggerType.MANUAL)
    return {
        "run_id"  : run_id,
        "trigger" : "MANUAL",
        "status"  : "started",
        "message" : f"Reconciling up to {req.limit} payments. Poll /reconcile/results/{run_id} for status."
    }


# ── Scheduler control ─────────────────────────────────────────────────────────

@app.get("/reconcile/schedule")
def get_schedule():
    return sched.status()


@app.put("/reconcile/schedule")
def update_schedule(cfg: ScheduleConfig):
    sched.update(cfg)
    return {"message": "Schedule updated", "schedule": sched.status()}


@app.post("/reconcile/schedule/pause")
def pause_schedule():
    sched.pause()
    return {"message": "EOD job paused", "schedule": sched.status()}


@app.post("/reconcile/schedule/resume")
def resume_schedule():
    sched.resume()
    return {"message": "EOD job resumed", "schedule": sched.status()}


# ── Results ───────────────────────────────────────────────────────────────────

@app.get("/reconcile/results")
def get_all_results(trigger: str | None = Query(None, description="MANUAL | SCHEDULED")):
    results = reconciler.get_all_results()
    if trigger:
        results = [r for r in results if r.trigger.upper() == trigger.upper()]
    return results


@app.get("/reconcile/results/{run_id}")
def get_result_by_id(run_id: str):
    return reconciler.get_result(run_id)


@app.get("/reconcile/payment/{payment_id}")
def reconcile_single(payment_id: str):
    return reconciler.reconcile_single(payment_id)


@app.get("/reconcile/discrepancies")
def get_discrepancies(
    severity : str | None = Query(None, description="LOW | MEDIUM | HIGH | CRITICAL"),
    layer    : str | None = Query(None, description="GATEWAY | LEDGER | BANK | MERCHANT")
):
    return reconciler.get_discrepancies(severity, layer)


@app.get("/reconcile/stats")
def get_stats():
    stats = reconciler.get_stats()
    stats["scheduler"] = sched.status()
    return stats
